import {modelPresentation} from './smart-cards.mjs';
import {applySearchFilter,searchModels,searchSortOptions,sortSearchMatches} from './smart-results-controls.mjs';
import {emptyCriteria,parseDemo,validateCriteria,recommend,reasons,powerLabels} from './smart-core.mjs';
const arrow='<svg aria-hidden="true"><use href="#arrow"/></svg>';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);
const examples=[['Family & hybrid','I have a family of 4, me, my wife and 2 kids. I want a hybrid car. I work in Nicosia and live in Larnaca. My budget is 33000 EUR.'],['Electric commute','I want an electric car for my daily commute, under €38,000. I can charge at home.'],['City driving','An automatic car for city driving, under €23,000.']];
const initialState=()=>({criteria:emptyCriteria(),submittedCriteria:emptyCriteria(),query:'',draft:'',sort:'recommended',filtersOpen:null,mode:'demo',busy:false,error:'',searched:false});
let state=initialState(), catalogue=null, modelMedia={}, timer=null, requestId=0;
const apiEnabled=false; // Enable only after wiring server/smart-search.mjs to a secured runtime endpoint.
const cataloguePromise=Promise.all([fetch('./data/vehicles.json').then(r=>{if(!r.ok)throw Error('catalogue');return r.json()}),fetch('./data/model-media.json').then(r=>r.ok?r.json():{}).catch(()=>({}))]).then(([data,media])=>{modelMedia=media;return catalogue=data}).catch(()=>null);
function composer(id,refine=false,value=''){return `<form class="smart-composer ${refine?'smart-refine smart-results-composer':''}" data-smart-form data-smart-mode="replace"><div class="smart-composer-head"><label for="${id}">${refine?'Your search':'Smart Search'}</label><span class="smart-mode">${apiEnabled?'Catalogue search':'Demo matching'}</span></div><div class="smart-input-wrap"><textarea id="${id}" name="prompt" rows="${refine?'2':'3'}" maxlength="1500" required aria-describedby="${id}-help" placeholder="${refine?'Describe the car, budget and features you have in mind…':''}" aria-label="${refine?'Edit your vehicle search':'Tell us what you need from your next car'}">${esc(value)}</textarea>${refine?'':`<div class="smart-typing" aria-hidden="true"><span></span><i></i></div>`}</div><div class="smart-composer-foot"><span id="${id}-help">${refine?'Change your description, then update your matches.':'Your life. Your journeys. Your budget.'}</span><button type="submit" class="smart-submit" ${state.busy?'disabled':''}>${state.busy?'Searching…':refine?'Update matches':'Find my matches'} ${arrow}</button></div><p class="smart-field-error" role="alert" hidden></p></form>`}
const filterIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/></svg>';
const chevron='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg>';
function filterSelect(field,label,options,value){return `<label class="smart-filter-field" for="smart-filter-${field}"><span>${label}</span><span class="smart-filter-select"><select id="smart-filter-${field}" data-smart-filter="${field}" ${state.busy||!catalogue?'disabled':''}>${options.map(([key,text])=>`<option value="${esc(key)}" ${String(value??'')===key?'selected':''}>${esc(text)}</option>`).join('')}</select>${chevron}</span></label>`}
function filterPanel(){
 const c=state.criteria,open=state.filtersOpen??!matchMedia('(max-width:700px)').matches;
 const count=[c.brand,c.model,c.body!=='any',c.powertrain!=='any',c.transmission!=='any',c.condition!=='any',c.budget,c.excludedBrands.length,c.excludedPowertrains.length].filter(Boolean).length;
 const brand=filterSelect('brand','Brand',[['','All brands'],...['Volkswagen','Audi','Škoda','CUPRA','SEAT'].map(name=>[name,name])],c.brand);
 const model=filterSelect('model','Model',[['','All models'],...searchModels(catalogue?.vehicles||[],c).map(name=>[name,name])],c.model);
 const body=filterSelect('body','Body type',[['any','Any body type'],['suv','SUV'],['hatchback','Hatchback'],['saloon','Saloon'],['estate','Estate'],['mpv','MPV'],['van','Van'],['pick-up','Pick-up'],['convertible','Convertible']],c.body);
 const power=filterSelect('powertrain','Engine type',[['any','All engine types'],['hybrid','All hybrid types'],['mild_hybrid','Mild hybrid'],['full_hybrid','Full hybrid'],['plug_in_hybrid','Plug-in hybrid'],['electric','Electric'],['petrol','Petrol'],['diesel','Diesel']],c.powertrain);
 const gearbox=filterSelect('transmission','Gearbox',[['any','Any gearbox'],['automatic','Automatic'],['manual','Manual']],c.transmission);
 const condition=filterSelect('condition','Vehicle status',[['any','Any vehicle status'],['new','New cars'],['test-drive','Test-drive cars'],['approved','Audi Approved']],c.condition);
 return `<details class="smart-results-filters" data-smart-filters ${open?'open':''}><summary><span class="smart-filter-summary"><span class="smart-filter-icon">${filterIcon}</span><strong>Filters</strong><span class="smart-filter-count">${count?count+' applied':'Find your fit'}</span></span>${chevron}</summary><div class="smart-filter-grid">${brand}${model}${body}${power}${gearbox}${condition}<label class="smart-filter-field" for="smart-filter-budget"><span>Maximum price</span><span class="smart-budget-input"><span aria-hidden="true">€</span><input id="smart-filter-budget" data-smart-filter="budget" type="number" inputmode="numeric" min="0" max="1000000" step="any" placeholder="No limit" value="${c.budgetKind==='purchase'&&c.budget?c.budget:''}" ${state.busy||!catalogue?'disabled':''}></span></label><div class="smart-filter-reset"><button type="button" class="button secondary" data-smart-reset-filters title="Restore the requirements from your submitted search" ${state.busy||!catalogue?'disabled':''}><span>Reset filters</span><span class="action-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 11a9 9 0 1 1 2.6 6.4M3 4v7h7"/></svg></span></button></div></div></details>`;
}
function sortControl(){return `<label class="smart-sort-control" for="smart-sort"><span>Sort by</span><span class="smart-filter-select"><select id="smart-sort" data-smart-sort ${state.busy||!catalogue?'disabled':''}>${searchSortOptions.map(([key,label])=>`<option value="${key}" ${state.sort===key?'selected':''}>${label}</option>`).join('')}</select>${chevron}</span></label>`}
function hero(){return `<div class="smart-hero smart-cinematic"><div class="smart-hero-media" aria-hidden="true"><video class="smart-hero-video" muted playsinline loop preload="none" poster="assets/smart-hero-poster.jpg" tabindex="-1" data-src="assets/smart-hero-film.mp4" data-mobile-src="assets/smart-hero-film-mobile.mp4"></video></div><div class="smart-hero-content"><div class="smart-hero-copy"><h1>Your next car.<br>Made personal.</h1><p>Tell us about your life. Find a car that fits.</p></div><div class="smart-hero-search">${composer('smartPrompt')}<div class="smart-examples" aria-label="Example vehicle searches">${examples.map(([l,q])=>`<button type="button" data-smart-example="${esc(q)}">${l}</button>`).join('')}</div><p class="smart-demo-note">Prototype · Demo matching. Published catalogue snapshot. Live AI and inventory are not connected.</p></div></div></div>`}
function conversionHero(){return `<div class="cro-hero home-frame"><div class="cro-copy"><p class="cro-eyebrow"><span class="cro-eyebrow-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/></svg></span><span>Your best choice for cars in Cyprus</span></p><h1>Find your next car.<br>Make it yours.</h1><p class="cro-description">Volkswagen, Audi, Škoda, CUPRA and SEAT. Compare models, prices and offers with a team here in Cyprus to help you choose.</p><ul class="cro-assurance" aria-label="Why choose Unicars"><li><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m3 11 2-6h14l2 6v8h-3v-3H6v3H3Z"/><path d="M3 11h18M7 13h1m8 0h1"/></svg><strong>5 leading brands</strong></li><li><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 12 12 4H4v8l8 8Z"/><circle cx="8" cy="8" r="1"/><path d="M16 11.5a2.5 2.5 0 1 0 0 4M11 13h4m-4 1.5h3"/></svg><strong>Clear model prices</strong></li><li><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/></svg><strong>Local expert care</strong></li></ul><div class="cro-actions"><a class="home-btn blue" href="#cars">Explore vehicles ${arrow}</a><a class="home-btn cro-secondary" href="#home-offers" data-home-scroll="home-offers">View latest offers ${arrow}</a></div><div class="cro-reviews" aria-label="Google customer rating: 4.3 out of 5 from 41 reviews, as shown in the supplied Google listing"><div class="cro-review-profiles" aria-hidden="true"><span><img src="https://images.pexels.com/photos/7191768/pexels-photo-7191768.jpeg?auto=compress&amp;cs=tinysrgb&amp;w=128&amp;h=128&amp;fit=crop&amp;crop=faces" alt="" width="36" height="36" loading="eager" referrerpolicy="no-referrer"></span><span><img src="https://images.pexels.com/photos/7400021/pexels-photo-7400021.jpeg?auto=compress&amp;cs=tinysrgb&amp;w=128&amp;h=128&amp;fit=crop&amp;crop=faces" alt="" width="36" height="36" loading="eager" referrerpolicy="no-referrer"></span><span><img src="https://images.pexels.com/photos/41005078/pexels-photo-41005078/free-photo-of-portrait-of-a-smiling-woman-in-soft-lighting.jpeg?auto=compress&amp;cs=tinysrgb&amp;w=128&amp;h=128&amp;fit=crop&amp;crop=faces" alt="" width="36" height="36" loading="eager" referrerpolicy="no-referrer"></span></div><div class="cro-review-pill"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 2 3 6.1 6.7 1-4.9 4.8 1.2 6.7-6-3.2-6 3.2 1.2-6.7-4.9-4.8 6.7-1Z"/></svg><span><strong>4.3 on Google</strong><span class="cro-review-separator" aria-hidden="true">·</span>41 reviews</span></div></div></div><div class="cro-visual" role="img" aria-label="Škoda Elroq in a Mediterranean setting"><video class="smart-hero-video cro-film" muted playsinline loop preload="none" poster="assets/smart-hero-poster.jpg" tabindex="-1" aria-hidden="true" data-src="assets/smart-hero-film.mp4" data-mobile-src="assets/smart-hero-film-mobile.mp4"></video><div class="cro-image-caption"><p>Find a car that feels like you.</p><strong>Great cars.<br>Closer to home.</strong><span>Discover Unicars in Cyprus.</span></div></div></div>`}
function setupHeroFilm(){const video=document.querySelector('.smart-hero-video');if(!video)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)');function play(){if(!video.src)video.src=matchMedia('(max-width: 800px)').matches?video.dataset.mobileSrc:video.dataset.src;video.muted=true;video.play().catch(()=>{});}reduced.addEventListener('change',()=>{if(reduced.matches)video.pause()});new IntersectionObserver(entries=>{if(!video.isConnected)return;if(entries[0].isIntersecting){if(!reduced.matches&&!navigator.connection?.saveData)play()}else video.pause()},{threshold:.1}).observe(video);}

function startTyping(){clearTimeout(timer);const input=document.getElementById('smartPrompt'),hint=document.querySelector('.smart-typing');if(!input||!hint)return;const prompts=['A hybrid for our family, under €33,000…','An electric car for my daily commute…','Something automatic for city driving…'];let n=0,i=0,back=false;const span=hint.querySelector('span');const reduced=matchMedia('(prefers-reduced-motion: reduce)');function tick(){if(!input.isConnected||input.value||document.activeElement===input)return;span.textContent=prompts[n].slice(0,i);if(reduced.matches){span.textContent=prompts[0];return;}let delay=back?22:48;if(!back&&i>=prompts[n].length){back=true;delay=1800}else if(back&&i<=0){back=false;n=(n+1)%prompts.length;delay=400}else i+=back?-1:1;timer=setTimeout(tick,delay)}tick();input.addEventListener('focus',()=>{clearTimeout(timer);hint.hidden=true});input.addEventListener('input',()=>{hint.hidden=!!input.value||document.activeElement===input});input.addEventListener('blur',()=>{if(!input.value){hint.hidden=false;tick()}})}
function chips(c){const values=[];if(c.source!=='any')values.push(c.source==='ehub'?'eHub cars & offers':'Model range');if(c.condition!=='any')values.push(c.condition==='approved'?'Audi Approved':c.condition==='test-drive'?'Test-drive / demo':"New cars");if(c.budget)values.push(money(c.budget)+(c.budgetKind==='monthly'?' / month':' maximum'));if(c.powertrain!=='any')values.push(powerLabels[c.powertrain]);if(c.brand)values.push(c.brand);if(c.model)values.push(c.model);if(c.family)values.push('Family use');if(c.passengers)values.push(c.passengers+' people');if(c.body!=='any')values.push(c.body==='suv'?'SUV':c.body);if(c.transmission!=='any')values.push(c.transmission);if(c.commute)values.push(c.commute);if(c.charging!=='unknown')values.push(c.charging==='yes'?'Charging available':'No home charging');c.excludedBrands.forEach(b=>values.push('Exclude '+b));c.excludedPowertrains.forEach(p=>values.push('Exclude '+powerLabels[p]));return values.map(v=>`<span>${esc(v)}</span>`).join('')}
function gallery(v,large=false){const {images}=modelPresentation(v,catalogue.vehicles,modelMedia);const id='gallery-'+v.id+(large?'-detail':'');return `<div class="smart-gallery ${large?'smart-gallery-large':''}" role="region" aria-label="${esc(v.brand+' '+v.model)} photos"><div class="smart-gallery-track" id="${id}" tabindex="0" aria-label="Vehicle photos. Use left and right arrow keys to change image.">${images.map((photo,i)=>`<div class="smart-gallery-slide" role="group" aria-label="Photo ${i+1} of ${images.length}"><img src="${esc(photo.src)}" alt="${esc(photo.alt)}" class="${photo.fit==='cover'?'photo-cover':''}" ${v.kind==='ehub_listing'?'style="object-position:center 75%"':''} loading="${large&&i===0?'eager':'lazy'}" draggable="false"></div>`).join('')}</div>${images.length>1?`<div class="smart-gallery-controls"><button class="smart-gallery-prev" data-gallery-step="-1" disabled aria-controls="${id}" aria-label="Previous ${esc(v.model)} photo">${arrow}</button><button class="smart-gallery-next" data-gallery-step="1" aria-controls="${id}" aria-label="Next ${esc(v.model)} photo">${arrow}</button></div><div class="smart-gallery-dots" aria-label="Choose a ${esc(v.model)} photo">${images.map((_,i)=>`<button data-gallery-index="${i}" aria-controls="${id}" aria-label="Show ${esc(v.model)} photo ${i+1}" aria-pressed="${i===0}"><span></span></button>`).join('')}</div>`:''}<span class="smart-gallery-count" aria-hidden="true">1 / ${images.length}</span><span class="smart-gallery-caption">${esc(images[0].caption||'Model image · equipment varies')}</span></div>`}
function vehicleCard(v,i,c){const presentation=modelPresentation(v,catalogue.vehicles,modelMedia),base=presentation.baseline,stock=v.kind==='ehub_listing',href=stock?'#ehub-car-'+v.listingId:v.model==='ID.3 Neo'?'#range-volkswagen-id-3-neo?version='+v.id:'#smart-vehicle-'+v.id;return `<article class="smart-vehicle">${gallery(v)}<div class="smart-vehicle-copy"><p class="smart-result-source ${stock?'is-stock':''}">${stock?'eHub · '+esc(v.condition):'Model range · Published version'}</p><div class="smart-card-heading"><p class="smart-vehicle-brand">${esc(v.brand)}</p><h3>${esc(v.model)}</h3></div><p class="smart-result-trim">${esc(v.trim)}</p><div class="smart-card-facts"><span>${esc(powerLabels[v.powertrain]||'See specifications')}</span>${v.transmission?`<span>${v.transmission==='automatic'?'Automatic':'Manual'}</span>`:''}${v.body?`<span>${esc(v.body==='suv'?'SUV':v.body==='mpv'?'MPV':v.body[0].toUpperCase()+v.body.slice(1))}</span>`:''}</div><div class="smart-card-price"><span>${stock?'eHub offer price':'Base model from'}</span><strong>${money(base.price)}</strong></div>${!stock&&presentation.hasPriceDifference?`<p class="smart-match-price">Matching version: <strong>${money(v.price)}</strong></p>`:''}${stock?`<p class="smart-stock-reference">${esc(v.reference)}${v.color?' · '+esc(v.color):''}</p>`:`<p class="smart-stock-reference">${1+(v.otherVersions?.length||0)} qualifying version${v.otherVersions?.length?'s':''} of this engine type</p>`}<p class="smart-card-budget">${c.budget&&c.budgetKind==='purchase'?(c.budget===v.price?'Within your budget':money(c.budget-v.price)+' below your budget'):'Published price · availability to confirm'}</p><a class="smart-card-link" href="${href}" aria-label="View ${esc(v.brand+' '+v.model)} vehicle page">View vehicle ${arrow}</a></div></article>`}

function resultsContent(){if(state.busy)return `<div class="smart-working" role="status"><span class="smart-spinner"></span><h2>Finding your starting point.</h2><p>Checking every imported model version and eHub listing.</p></div>`;if(state.error)return `<div class="smart-empty"><h2>We couldn’t load the catalogue.</h2><p>Please try again. You can still browse the vehicle range.</p><button class="smart-submit" data-smart-retry>Try again ${arrow}</button><a href="#cars">Browse vehicles ${arrow}</a></div>`;
 if(!state.searched)return `<div class="smart-empty"><h2>What do you have in mind?</h2><p>Choose an example, or describe what you want from your next vehicle.</p><div class="smart-start-examples">${examples.map(([l,q])=>`<button data-smart-example="${esc(q)}">${l} ${arrow}</button>`).join('')}</div></div>`;
 const c=state.criteria;
 if(c.intent!=='vehicle'){const route={service:['Need help with your current car?','Explore support or request a service appointment.','owners','Explore support'],charging:['Looking for a charger?','The charging journey has its own dedicated place.','chargers','Find a charger'],contact:['Let’s get you to the right team.','Choose the contact route for your question.','contact','Contact Unicars'],unknown:['Let’s make that more specific.','Demo mode understands common vehicle needs. Try a budget, brand or powertrain, or start a new search.','cars','Browse all models']}[c.intent];return `<div class="smart-empty"><h2>${route[0]}</h2><p>${route[1]}</p><a class="smart-submit" href="#${route[2]}">${route[3]} ${arrow}</a></div>`}
 const result=recommend(catalogue.vehicles,c),all=recommend(catalogue.vehicles,{...c,source:'any'}),modelCount=all.matches.filter(v=>v.kind!=='ehub_listing').length,stockCount=all.matches.filter(v=>v.kind==='ehub_listing').length;
 const matches=sortSearchMatches(result.matches,state.sort);
 const sourceTabs=`<div class="smart-source-tabs" role="group" aria-label="Search result source">${[['any','All results',all.matches.length],['models','Model options',modelCount],['ehub','eHub cars',stockCount]].map(([value,label,n])=>`<button type="button" data-smart-source="${value}" aria-pressed="${c.source===value}">${label}<span>${n}</span></button>`).join('')}</div>`;
 if(result.issues.includes('monthly_budget'))return `<div class="smart-question"><h2>Is that your monthly budget?</h2><p>This search compares published purchase prices. Edit the search above with your total purchase budget; finance repayments need a separate, verified calculation.</p></div>`;
 const warning=result.warnings.length?`<details class="smart-checks"><summary>What still needs checking ${arrow}</summary>${result.warnings.map(w=>`<p>${esc(w)}</p>`).join('')}</details>`:'';
 const charging=result.needsChargingChoice?`<div class="smart-charging-question"><div><h3>Could you charge regularly?</h3><p>This helps put an electric or plug-in choice in context.</p></div><div><button data-smart-charging="yes">Yes</button><button data-smart-charging="no">No</button><button data-smart-charging="unknown">Not sure</button></div></div>`:'';
 if(!result.matches.length)return `${sourceTabs}<div class="smart-results-controls"><p>0 matching options</p>${sortControl()}</div><div class="smart-empty"><h2>No published matches for these requirements.</h2><p>We haven’t changed your requirements. Try a different requirement or ask the team about vehicles not currently published.</p><div class="smart-empty-actions">${c.budget?'<button data-smart-remove-budget>Search without a price limit '+arrow+'</button>':''}${c.powertrain!=='any'?'<button data-smart-remove-power>Consider other powertrains '+arrow+'</button>':''}<a href="#contact">Ask the team ${arrow}</a></div></div>${warning}`;
 return `${sourceTabs}<p class="smart-scope-note">Matches apply budget, brand/model, engine, body, gearbox and vehicle-status filters. Other requirements need confirmation with Unicars.</p><div class="smart-results-heading"><h2>${matches.length} matching vehicle option${matches.length===1?'':'s'}</h2>${sortControl()}</div><p class="smart-sort-note">${state.sort.startsWith('price')?'Sorted by the published price of the matching version.':'Published model options and eHub cars · availability to confirm.'}</p><div class="smart-vehicle-grid">${matches.map((v,i)=>vehicleCard(v,i,c)).join('')}</div>${charging}${warning}`;
}
function page(){return `<div class="smart-page smart-results-page home-frame"><div class="smart-results-toolbar"><a href="#home" class="smart-back">Back to home ${arrow}</a><button class="smart-reset" data-smart-reset>Clear search <svg aria-hidden="true"><use href="#close"/></svg></button></div><div class="smart-page-title"><h1>${state.searched?'Your matches.':'Find your next car.'}</h1><span>${state.mode==='live'?'AI-assisted search':'Smart Search · Published snapshot'}</span></div><div class="smart-search-edit">${composer('smartResultsPrompt',true,state.draft)}</div>${state.searched?`<div class="smart-active-criteria"><span>Current requirements</span><div class="smart-criteria">${chips(state.criteria)||'<span>All published vehicles</span>'}</div></div>`:''}${state.criteria.intent==='vehicle'?filterPanel():''}<div id="smartResults" aria-busy="${state.busy}">${state.apiFallback?'<p class="smart-checks">The AI connection is unavailable. These results use demo matching; please check the recorded filters.</p>':''}${resultsContent()}</div><div class="smart-pilot-note"><strong>${state.mode==='live'?'AI-assisted interpretation':'Demo matching · Live AI is not connected'}</strong><p>All imported priced versions and specific eHub listings. No live stock connection. Family suitability and specifications need confirmation. Model-range starting prices may refer to a different powertrain; search eligibility always uses the matching version’s price. Photos illustrate model ranges; equipment may vary.</p><div class="smart-data-links"><a href="data/vehicles.csv" download>Download complete catalogue ${arrow}</a><a href="data/model-media.json" target="_blank" rel="noopener">Image sources & price references ${arrow}</a></div></div><p id="smartAnnouncement" class="smart-sr" role="status" aria-live="polite"></p></div>`}
function versionLinks(v){const versions=catalogue.vehicles.filter(x=>x.kind!=='ehub_listing'&&x.brand===v.brand&&x.model===v.model);if(versions.length<2)return '';return `<details class="smart-detail-versions"><summary>${versions.length} published model versions ${arrow}</summary><div>${versions.map(x=>`<a href="#smart-vehicle-${x.id}" ${x.id===v.id?'aria-current="page"':''}><span>${esc(x.trim)}<small>${esc(powerLabels[x.powertrain])}${x.id===v.id?' · Selected':''}</small></span><strong>${money(x.price)}</strong></a>`).join('')}</div></details>`}
function detail(id){const v=catalogue?.vehicles.find(v=>v.id===id);if(!v)return `<div class="smart-page home-frame"><h1>This version is not in the published snapshot.</h1><a href="#smart-search">Back to results</a></div>`;return `<div class="smart-page home-frame"><a href="#smart-search" class="smart-back">← Back to your shortlist</a><div class="smart-detail"><div class="smart-detail-image">${gallery(v,true)}</div><div><p>${esc(v.brand)}</p><h1>${esc(v.model)}</h1><p class="smart-detail-trim">${esc(v.trim)}</p><p class="smart-model-start">Model range from <strong>${money(modelPresentation(v,catalogue.vehicles,modelMedia).baseline.price)}</strong>. Selected version: ${esc(v.trim)}.</p><div class="smart-price"><strong>${money(v.price)}</strong><span>Selected version · Published list price · ${esc(v.sourceIssued)}</span></div><dl><div><dt>Powertrain</dt><dd>${powerLabels[v.powertrain]}</dd></div><div><dt>Transmission</dt><dd>${v.transmission?esc(v.transmission==='automatic'?'Automatic':'Manual'):'Not stated for this source row'}</dd></div><div><dt>Availability</dt><dd>Requires confirmation</dd></div></dl>${versionLinks(v)}${v.dateNeedsConfirmation?'<p class="smart-date-warning">The source PDF is future dated. Confirm its date and price with Unicars.</p>':''}<p class="smart-detail-disclosure">Published sources checked 20 November 2026. Final price, applicable offers, equipment and availability require confirmation. Passenger capacity, child-seat fit and luggage space have not been verified for every version.</p><div class="smart-detail-actions"><a class="smart-submit" href="${v.localDocument||v.source}" target="_blank" rel="noopener">View official price list ${arrow}</a><a class="smart-enquiry" href="#test-drive?model=smart-vehicle-${v.id}">Book a test drive ${arrow}</a></div></div></div></div>`}
function drawPage(){
 const root=document.getElementById('smartSearchPage');
 if(root){
  const active=root.contains(document.activeElement)?document.activeElement:null;
  const focus=active?{id:active.id,start:active.selectionStart,end:active.selectionEnd}:null;
  root.innerHTML=page();
  if(focus?.id){const next=document.getElementById(focus.id);next?.focus({preventScroll:true});if(focus.start!=null&&next?.setSelectionRange)try{next.setSelectionRange(focus.start,focus.end)}catch{}}
  const live=root.querySelector('#smartAnnouncement');
  if(state.searched&&!state.busy)requestAnimationFrame(()=>{if(live?.isConnected)live.textContent=state.criteria.intent==='vehicle'&&catalogue?recommend(catalogue.vehicles,state.criteria).matches.length+' matching vehicle options. Results updated.':'Your search results have been updated.'});
 }
 const detailRoot=document.getElementById('smartVehiclePage');if(detailRoot)detailRoot.innerHTML=detail(location.hash.slice('#smart-vehicle-'.length));
}
function mount(){const intro=document.querySelector('.campaign-hero .hero-intro');if(intro){intro.outerHTML=location.hash==='#home-cro'?conversionHero():hero();startTyping();setupHeroFilm()}if(document.getElementById('smartSearchPage')&&!document.querySelector('.smart-page'))drawPage();if(document.getElementById('smartVehiclePage')&&!document.querySelector('.smart-detail'))drawPage()}
function update(patch){if(!catalogue)return;state.criteria=validateCriteria({...state.criteria,...patch});state.searched=true;state.error='';drawPage()}
let filterTimer;
document.addEventListener('input',event=>{
 const input=event.target;
 if(input.matches('#smartResultsPrompt'))state.draft=input.value;
 if(input.matches('[data-smart-filter="budget"]')){clearTimeout(filterTimer);filterTimer=setTimeout(()=>{if(input.isConnected&&input.checkValidity())update(applySearchFilter(state.criteria,'budget',input.value,catalogue?.vehicles||[]))},350);}
});
document.addEventListener('change',event=>{
 const input=event.target;
 if(input.matches('[data-smart-filter]')){clearTimeout(filterTimer);if(!input.checkValidity()){input.reportValidity();return;}update(applySearchFilter(state.criteria,input.dataset.smartFilter,input.value,catalogue?.vehicles||[]));}
 else if(input.matches('[data-smart-sort]')){state.sort=searchSortOptions.some(([key])=>key===input.value)?input.value:'recommended';drawPage();}
});
document.addEventListener('toggle',event=>{if(event.target.isConnected&&event.target.matches('[data-smart-filters]'))state.filtersOpen=event.target.open;},true);
async function search(text,refine=false){text=text.trim();if(!text)return;const req=++requestId;state.query=refine&&state.query?state.query+'\nRefinement: '+text:text;state.draft=state.query;clearTimeout(filterTimer);const previous=refine?state.criteria:emptyCriteria();if(!refine)state.hybridExplained=false;state.busy=true;state.error='';state.searched=true;if(location.hash!=='#smart-search')location.hash='smart-search';else drawPage();await cataloguePromise;if(req!==requestId)return;if(!catalogue){state.busy=false;state.error='catalogue';drawPage();return}let criteria;
 if(apiEnabled){try{const response=await fetch('/api/smart-search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:text,previous})});if(!response.ok)throw Error('unavailable');const body=await response.json();criteria=validateCriteria(body.criteria);state.mode=body.mode==='live'?'live':'demo';}catch{state.mode='demo';criteria=parseDemo(text,previous,catalogue.vehicles);state.error='';state.apiFallback=true;}}else{criteria=parseDemo(text,previous,catalogue.vehicles);state.mode='demo'}
 if(req!==requestId)return;state.criteria=criteria;state.submittedCriteria=validateCriteria(criteria);state.busy=false;drawPage();window.scrollTo({top:0,behavior:'instant'});document.querySelector('.smart-page-title h1')?.setAttribute('tabindex','-1');document.querySelector('.smart-page-title h1')?.focus({preventScroll:true});}
document.addEventListener('submit',e=>{if(e.target.matches('[data-smart-form]')){e.preventDefault();const input=e.target.querySelector('textarea');if(input.value.trim().length<3){const error=e.target.querySelector('.smart-field-error');error.hidden=false;error.textContent='Tell us a little more, or choose an example.';input.focus();return}search(input.value,e.target.dataset.smartMode==='refine'&&state.searched)}});
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.hasAttribute('data-smart-reset-filters')){clearTimeout(filterTimer);update(state.submittedCriteria||emptyCriteria());return;}if(t.hasAttribute('data-smart-source')){update({source:t.dataset.smartSource});return;}if(t.dataset.smartExample){const input=document.getElementById('smartPrompt');if(input)input.value=t.dataset.smartExample;search(t.dataset.smartExample)}else if(t.hasAttribute('data-smart-power')){state.hybridExplained=true;update({powertrain:t.dataset.smartPower});}else if(t.hasAttribute('data-smart-charging'))update({charging:t.dataset.smartCharging});else if(t.hasAttribute('data-smart-remove-budget'))update({budget:null});else if(t.hasAttribute('data-smart-remove-power'))update({powertrain:'any',excludedPowertrains:[]});else if(t.hasAttribute('data-smart-reset')){requestId++;clearTimeout(filterTimer);state=initialState();drawPage();document.getElementById('smartResultsPrompt')?.focus({preventScroll:true})}else if(t.hasAttribute('data-smart-retry')){location.reload()}else if(t.dataset.smartEnquiry){const v=catalogue.vehicles.find(v=>v.id===t.dataset.smartEnquiry);if(!v)return;const dialog=document.getElementById('requestDialog');document.getElementById('dialogTitle').textContent='Ask about '+v.brand+' '+v.model;document.getElementById('dialogDescription').textContent=v.trim+' · '+money(v.price)+' published list price. This demonstration does not send an enquiry.';document.getElementById('requestModelField')?.setAttribute('hidden','');const modelSelect=document.getElementById('requestModel');if(modelSelect)modelSelect.required=false;dialog.querySelector('.form-fields').hidden=false;dialog.querySelector('.form-success').hidden=true;dialog.querySelector('button[type="submit"]').hidden=false;document.body.classList.add('dialog-open');dialog.showModal();}});
function moveGallery(track,index){const count=track.children.length;index=Math.max(0,Math.min(count-1,index));track.scrollTo({left:index*track.clientWidth,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
function syncGallery(track){const root=track.closest('.smart-gallery'),index=Math.round(track.scrollLeft/track.clientWidth),photos=track.children;root.querySelectorAll('[data-gallery-index]').forEach((button,i)=>button.setAttribute('aria-pressed',String(i===index)));root.querySelector('.smart-gallery-count').textContent=(index+1)+' / '+photos.length;const key=track.id.replace(/^gallery-/,'').replace(/-detail$/,'');const v=catalogue.vehicles.find(v=>v.id===key);if(v){const images=modelPresentation(v,catalogue.vehicles,modelMedia).images;root.querySelector('.smart-gallery-caption').textContent=images[index]?.caption||'Model image · equipment varies';}const prev=root.querySelector('[data-gallery-step="-1"]'),next=root.querySelector('[data-gallery-step="1"]');if(prev)prev.disabled=index===0;if(next)next.disabled=index===photos.length-1;}
document.addEventListener('click',e=>{const control=e.target.closest('[data-gallery-step],[data-gallery-index]');if(!control)return;const track=document.getElementById(control.getAttribute('aria-controls'));if(!track)return;const index=control.hasAttribute('data-gallery-index')?Number(control.dataset.galleryIndex):Math.round(track.scrollLeft/track.clientWidth)+Number(control.dataset.galleryStep);moveGallery(track,index);});
document.addEventListener('scroll',e=>{if(e.target.matches?.('.smart-gallery-track'))syncGallery(e.target)},true);
document.addEventListener('keydown',e=>{if(!e.target.matches('.smart-gallery-track')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const track=e.target,index=e.key==='Home'?0:e.key==='End'?track.children.length-1:Math.round(track.scrollLeft/track.clientWidth)+(e.key==='ArrowRight'?1:-1);moveGallery(track,index)});
document.addEventListener('keydown',e=>{if(e.target.matches('[data-smart-form] textarea')&&e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();e.target.form.requestSubmit()}});
const observer=new MutationObserver(()=>mount());observer.observe(document.getElementById('main'),{childList:true});cataloguePromise.then(()=>{mount();drawPage()});mount();
